const result = $input.first().json;
const rows = Array.isArray(result) ? result : [];

if (rows.length === 0) {
  console.log('[renew-watch] Nenhum watch channel precisando de renovação.');
  return [];
}

console.log(`[renew-watch] ${rows.length} clientes com watch channel expirando.`);

return rows.map(row => ({
  json: {
    client_id:     row.client_id,
    access_token:  row.access_token,
    refresh_token: row.refresh_token,
    token_expiry:  row.token_expiry,
    calendar_id:   row.calendar_id ?? 'primary',
    watch_expiry:  row.watch_expiry,
  }
}));

const row = $input.first().json;
const expiry = row.token_expiry ? new Date(row.token_expiry).getTime() : 0;
const needsRefresh = expiry - Date.now() < 5 * 60 * 1000;
return [{ json: { ...row, needs_token_refresh: needsRefresh } }];

const refreshResult = $input.first().json;
const prev = $('Checar Token OAuth2').first().json;
return [{ json: {
  ...prev,
  access_token: refreshResult.access_token ?? prev.access_token,
  token_expiry: refreshResult.expires_in
    ? new Date(Date.now() + refreshResult.expires_in * 1000).toISOString()
    : prev.token_expiry
} }];

