const watchResult = $input.first().json;
const ctx = $('Checar Token OAuth2').first().json;

if (!watchResult?.id) {
  console.error(`[renew-watch] Falha ao renovar watch para cliente ${ctx.client_id}:`, JSON.stringify(watchResult));
  return [];
}

const newExpiry = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();
console.log(`[renew-watch] Watch renovado para ${ctx.client_id}: ${watchResult.id} | expira: ${newExpiry}`);

return [{ json: {
  client_id:        ctx.client_id,
  new_channel_id:   watchResult.id,
  new_resource_id:  watchResult.resourceId ?? '',
  new_expiry:       newExpiry,
} }];

const prev = $('Processar Resultado').first().json;
console.log(`[renew-watch] ✅ Cliente ${prev.client_id} — watch channel renovado com sucesso.`);
return [{ json: { success: true, client_id: prev.client_id, new_channel_id: prev.new_channel_id, expires: prev.new_expiry } }];
